import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { useRouter, type NextRouter } from 'next/router'
import { SearchBar } from '@/components/SearchBar'

/**
 * Checks for the autocomplete challenge. Do not edit this file: run
 * `npm run verify:challenge`. Only the router and the network are fake; the
 * clock is real, so the debounce really waits.
 */

jest.mock('next/router', () => ({ useRouter: jest.fn() }))

const push = jest.fn()
const fetchMock = jest.fn()

function respondWith(suggestions: string[]) {
  fetchMock.mockResolvedValue({ ok: true, json: async () => ({ suggestions }) })
}

const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

beforeEach(() => {
  push.mockReset()
  fetchMock.mockReset()
  global.fetch = fetchMock
  jest.mocked(useRouter).mockReturnValue({ query: {}, push } as unknown as NextRouter)
})

async function typeInSearch(text: string) {
  const user = userEvent.setup()
  render(<SearchBar />)
  await user.type(screen.getByLabelText('Buscar'), text)
  return user
}

describe('challenge: autocomplete', () => {
  it('shows the suggestions from /api/suggestions while the person types', async () => {
    respondWith(['Guarda compartilhada', 'Guarda unilateral'])
    await typeInSearch('guarda')

    const options = await screen.findAllByRole('option')
    expect(options.map((option) => option.textContent)).toEqual(['Guarda compartilhada', 'Guarda unilateral'])
  })

  it('debounce: calls the API once, after the person stops typing', async () => {
    respondWith(['Guarda compartilhada'])
    await typeInSearch('guarda')

    await screen.findAllByRole('option')
    expect(fetchMock).toHaveBeenCalledTimes(1)
    expect(String(fetchMock.mock.calls[0]?.[0])).toContain('/api/suggestions?q=guarda')
  })

  it('does not call the API with fewer than 2 letters', async () => {
    respondWith(['Guarda compartilhada'])
    await typeInSearch('g')

    await wait(600)
    expect(fetchMock).not.toHaveBeenCalled()
  })

  it('clicking a suggestion runs the search', async () => {
    respondWith(['Guarda compartilhada'])
    const user = await typeInSearch('guarda')

    await user.click(await screen.findByRole('option', { name: 'Guarda compartilhada' }))

    expect(push).toHaveBeenCalledWith('/busca?q=Guarda+compartilhada')
  })
})
